(function(root){
  'use strict';
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const url=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?escape(u.href):'#';}catch{return '#';}};
  const date=value=>value?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',day:'numeric',month:'short',year:'numeric'}).format(new Date(value)):'Unknown';
  const confidence=(kind,explanation='')=>`<span class="confidence confidence-${kind.toLowerCase().replace(/[^a-z]/g,'')}" ${explanation?`title="${escape(explanation)}"`:''}>${escape(kind)}</span>`;
  const key='start-2026-shortlist-v1';
  let projects=new Map(),saved=new Set(),data=null,storageAvailable=true;
  try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))saved=new Set(stored.filter(id=>typeof id==='string'));}catch{storageAvailable=false;}
  function announce(message){let live=document.getElementById('save-status');if(!live){live=document.createElement('div');live.id='save-status';live.className='save-toast';live.setAttribute('role','status');document.body.append(live);}live.textContent=message;clearTimeout(announce.timer);announce.timer=setTimeout(()=>live.textContent='',3500);}
  function sync(){
    document.querySelectorAll('[data-save]').forEach(button=>{const yes=saved.has(button.dataset.save);button.textContent=yes?'Saved':'Save';button.setAttribute('aria-pressed',String(yes));button.setAttribute('aria-label',`${yes?'Remove':'Save'} ${projects.get(button.dataset.save)?.name||'project'}${yes?' from shortlist':''}`);button.classList.toggle('is-saved',yes);});
    document.querySelectorAll('[data-saved-count]').forEach(el=>el.textContent=saved.size);
  }
  function persist(){try{localStorage.setItem(key,JSON.stringify([...saved]));storageAvailable=true;}catch{storageAvailable=false;}sync();root.dispatchEvent(new CustomEvent('shortlistchange'));}
  function toggleSave(id){if(!projects.has(id))return;const had=saved.has(id);if(had)saved.delete(id);else saved.add(id);persist();announce(`${had?'Removed from':'Added to'} your shortlist.${storageAvailable?' Saved on this device.':' Browser storage is unavailable; saved for this visit only.'}`);}
  function init(payload){data=payload;projects=new Map(payload.projects.map(p=>[p.id,p]));saved=new Set([...saved].filter(id=>projects.has(id)));sync();}
  const field=(label,value,kind,source)=>`<div class="confidence-field"><div><strong>${escape(label)}</strong>${confidence(kind)}</div><p>${escape(value)}</p>${source?`<a href="${url(source)}" target="_blank" rel="noopener">View source</a>`:''}</div>`;
  function openProject(id){
    const p=projects.get(id);if(!p)return;
    const a=GalleryAvailability.availabilityFor(p),dialog=document.getElementById('project-dialog');
    const narrative=(title,evidence,unknown)=>`<details class="evidence-detail"><summary>${escape(title)} ${confidence(evidence?'Developer-reported':'Unknown')}</summary>${evidence?`<blockquote>${escape(evidence)}</blockquote><a href="${url(p.url)}" target="_blank" rel="noopener">Read the project story</a>`:`<p>${escape(unknown)}</p>`}</details>`;
    const badges=(p.teamAwardBadges||[]).filter(b=>b.beforeDeadline);
    document.getElementById('detail-content').innerHTML=`${p.heroImage?`<img class="detail-cover" src="${url(p.image)}" alt="${escape(p.name)} cover" referrerpolicy="no-referrer">`:''}<p class="eyebrow">PROJECT / ${escape(p.id)}</p><h2 class="detail-title" id="detail-title">${escape(p.name)}</h2><p class="detail-tagline">${escape(p.tagline)}</p><div class="detail-links"><button class="button save-button" data-save="${escape(p.id)}">Save</button><a class="button" href="${url(p.url)}" target="_blank" rel="noopener">Devpost project</a>${p.videoUrls?.length?`<a class="button" href="${url(p.videoUrls[0])}" target="_blank" rel="noopener">Watch video</a>`:''}</div><section class="availability-detail"><div>${confidence(a.confidence)}<span class="source-date">Source checked ${date(a.sourceCheckedAt)}</span></div><h3>${escape(a.label)}</h3><p>${escape(a.reason)}</p>${a.primaryUrl?`<a class="button access-button" href="${url(a.primaryUrl)}" target="_blank" rel="noopener">${a.state==='share'?'Open Meta link':a.state==='access'?'Open access link':a.state==='store'?'Open store link':a.state==='download'?'Open download page':a.state==='web'?'Open web link':'Visit project website'}</a>`:''}<p class="access-caution">Linked destinations and installs have not been tested.</p></section><section class="detail-section"><h3>What the evidence supports</h3><div class="confidence-fields">${field('Listed collaborators',p.teamSize?String(p.teamSize):'No public team count established',p.teamSize?'Observed':'Unknown',p.url)}${field('Category',p.estimatedCategory==='Unclassified'?'No clear keyword category':p.estimatedCategory+' · keyword estimate',p.estimatedCategory==='Unclassified'?'Unknown':'Estimated',p.url)}${field('Price, languages & supported devices','Not established from this snapshot','Unknown')}${field('Official submission track & exact submission time','Not publicly exposed in the inspected sources','Unknown')}</div></section><section class="detail-section"><h3>Developer statements</h3><p>Mentions are not independently verified; a missing mention stays unknown.</p>${narrative('Trial / demo',p.trialEvidence,'No matching trial/demo offer phrase was captured. A trial may still exist.')}${narrative('New or existing app',p.newAppEvidence,'The official division and app history have not been established.')}</section><section class="detail-section"><h3>People & tools</h3><p>${(p.team||[]).map(t=>`<a href="${url(t.url)}" target="_blank" rel="noopener">${escape(t.name)}</a>`).join(', ')||'No listed collaborators captured.'}</p><div class="detail-tags">${(p.tags||[]).map(t=>`<span>${escape(t)}</span>`).join('')}</div><p>${confidence('Developer-reported')} Technology tags are self-reported.</p></section><details class="evidence-detail"><summary>Dates, engagement & award evidence</summary><p>First “started this project” activity: ${date(p.publishedAt)}. Record creation: ${date(p.createdAt)}. Neither is a submission timestamp.</p><p>${Number(p.likes).toLocaleString('en-GB')} public likes · ${Number(p.comments).toLocaleString('en-GB')} comments · ${p.screenshots??'Unknown'} screenshots. Engagement may predate this competition.</p>${badges.length?`<p>A listed member has prior Devpost winner-badge evidence. Prizes can include participation perks; this does not establish a competitive or Meta award.</p><ul>${badges.map(b=>`<li><a href="${url(b.sourceUrl)}" target="_blank" rel="noopener">${escape(b.memberName)} · ${escape(b.title)}</a> · ${date(b.achievedDate)}</li>`).join('')}</ul>`:'<p>Prior wins remain unknown. Absence of a badge does not establish that the team has never won.</p>'}</details><details class="evidence-detail"><summary>All public links</summary><ul>${(p.links||[]).map(l=>`<li><a href="${url(l.url)}" target="_blank" rel="noopener">${escape(l.label||l.url)}</a></li>`).join('')||'<li>No public project links were captured.</li>'}</ul></details><p class="detail-analytics-link"><a href="analytics.html#methodology">Detailed analytics & methodology</a></p>`;
    sync();dialog.showModal();document.getElementById('detail-content').scrollTop=0;
  }
  document.addEventListener('click',event=>{const button=event.target.closest('[data-save]');if(button){event.preventDefault();event.stopPropagation();toggleSave(button.dataset.save);}const open=event.target.closest('[data-open]');if(open)openProject(open.dataset.open);});
  root.addEventListener('storage',event=>{if(event.key!==key)return;try{const value=JSON.parse(event.newValue||'[]');if(Array.isArray(value)){saved=new Set(value.filter(id=>typeof id==='string'&&projects.has(id)));sync();root.dispatchEvent(new CustomEvent('shortlistchange'));}}catch{}});
  root.GalleryTools={init,openProject,toggleSave,escape,url,date,confidence,sync,announce,savedIds:()=>[...saved]};
})(globalThis);
